\sqrt{\frac{a_n}{a_1}}+n-2 +\sqrt{\frac{a_1}{a_n}} &\le n+\frac{1}{2}
\sqrt{\frac{a_n}{a_1}}+\sqrt{\frac{a_1}{a_n}} &\le \frac{5}{2}.
