&= \frac{(t^2(x+y+z) + xyz)(x^2 t^2 + y^2z^2 - x^2y^2 - x^2z^2 - (t^2-x^2)(xy + xz-yz))}{2(t^2-x^2)(t^2 yz (x+y+z) -xyz(t^2 + xy + xz)} 
&= \frac{(t^2(x+y+z) + xyz)(x-y)(x-z)(t^2 + xy + xz + yz)}{2yz(t^2-x^2)^2(y+z)}
\end{align*}
Then 
\begin{align*}
\overline{\alpha} &= \frac{ (\frac{1}{t^2} ( \frac1x + \frac1y + \frac1z) + \frac1{xyz})(\frac1x - \frac1y )(\frac1x - \frac1z) (\frac1{t^2} + \frac1{xy} + \frac1{xz} + \frac1{yz} )}{\frac2{yz} (\frac1{t^2} - \frac1{x^2})^2 (\frac1y + \frac1z)} 
&= \frac{ (xy + yz + zx + t^2)(y-x)(z-x)(xyz + t^2(x+y+z))}{2yz(x^2-t^2)^2(z+x)} = \alpha.
\end{align*}
Hence  $K,G,D$  are collinear, so the problem is done.

